1	"use client";
2	
3	import {
4	  useCallback,
5	  useEffect,
6	  useRef,
7	  useState,
8	  useTransition,
9	  type ClipboardEvent,
10	} from "react";
11	import {
12	  listConversations,
13	  replyToConversation,
14	  replyWithAttachment,
15	  closeConversation,
16	  closeAllConversations,
17	  assignConversation,
18	  signalAgentTyping,
19	} from "@/lib/actions-chat";
20	
21	/**
22	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
23	 * first) and a thread view with a reply box. Polls `listConversations` every
24	 * few seconds so new visitor messages appear without a manual refresh.
25	 */
26	
27	type Attachment = { id: string; mime: string; sizeBytes: number };
28	type Msg = {
29	  id: string;
30	  sender: string;
31	  body: string;
32	  createdAt: string;
33	  attachment?: Attachment | null;
34	};
35	type Convo = {
36	  id: string;
37	  visitorId: string;
38	  userId: string | null;
39	  name: string | null;
40	  email: string | null;
41	  status: string;
42	  assignedToId: string | null;
43	  assignedToName: string | null;
44	  unreadForAgent: boolean;
45	  lastMessageAt: string;
46	  createdAt: string;
47	  visitorTyping: boolean;
48	  messages: Msg[];
49	};
50	
51	/** Three-dot "typing…" pulse, matching the widget's indicator. */
52	function TypingDots() {
53	  return (
54	    <span className="flex items-center gap-1" aria-hidden="true">
55	      {[0, 150, 300].map((delay) => (
56	        <span
57	          key={delay}
58	          className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-300"
59	          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
60	        />
61	      ))}
62	    </span>
63	  );
64	}
65	
66	/** Small robot glyph used to mark AI-assistant messages, matching the widget. */
67	function BotIcon({ className = "" }: { className?: string }) {
68	  return (
69	    <svg
70	      width="11"
71	      height="11"
72	      viewBox="0 0 24 24"
73	      fill="none"
74	      stroke="currentColor"
75	      strokeWidth="2"
76	      strokeLinecap="round"
77	      strokeLinejoin="round"
78	      className={className}
79	      aria-hidden
80	    >
81	      <path d="M12 2v3M5 8h14a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1zM9 13h.01M15 13h.01" />
82	    </svg>
83	  );
84	}
85	
86	const POLL_MS = 5000;
87	
88	// Client-side pre-checks only; replyWithAttachment re-validates by signature.
89	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
90	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
91	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
92	
93	function imageError(file: File): string | null {
94	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
95	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
96	  return null;
97	}
98	
99	function timeAgo(iso: string): string {
100	  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
101	  if (s < 60) return `${s}s ago`;
102	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
103	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
104	  return `${Math.floor(s / 86400)}d ago`;
105	}
106	
107	export default function ChatInbox({ initial }: { initial: Convo[] }) {
108	  const [convos, setConvos] = useState<Convo[]>(initial);
109	  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
110	  const [draft, setDraft] = useState("");
111	  const [query, setQuery] = useState("");
112	  const [error, setError] = useState("");
113	  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
114	  const [pending, start] = useTransition();
115	  const scrollRef = useRef<HTMLDivElement>(null);
116	  const fileInputRef = useRef<HTMLInputElement>(null);
117	  const lastTypingPingRef = useRef(0); // throttle "agent is typing" pings
118	
119	  useEffect(() => {
120	    return () => {
121	      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
122	    };
123	  }, [pendingImage]);
124	
125	  function pickImage(file: File | null | undefined) {
126	    if (!file) return;
127	    const err = imageError(file);
128	    if (err) {
129	      setError(err);
130	      return;
131	    }
132	    setError("");
133	    setPendingImage((prev) => {
134	      if (prev) URL.revokeObjectURL(prev.url);
135	      return { file, url: URL.createObjectURL(file) };
136	    });
137	  }
138	
139	  function clearImage() {
140	    setPendingImage((prev) => {
141	      if (prev) URL.revokeObjectURL(prev.url);
142	      return null;
143	    });
144	    if (fileInputRef.current) fileInputRef.current.value = "";
145	  }
146	
147	  function onPaste(e: ClipboardEvent) {
148	    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
149	      i.type.startsWith("image/")
150	    );
151	    if (item) {
152	      const file = item.getAsFile();
153	      if (file) {
154	        e.preventDefault();
155	        pickImage(file);
156	      }
157	    }
158	  }
159	
160	  const refresh = useCallback(async () => {
161	    try {
162	      const rows = await listConversations();
163	      setConvos(rows);
164	    } catch {
165	      /* transient — next poll retries */
166	    }
167	  }, []);
168	
169	  useEffect(() => {
170	    const t = setInterval(refresh, POLL_MS);
171	    return () => clearInterval(t);
172	  }, [refresh]);
173	
174	  const selected = convos.find((c) => c.id === selectedId) ?? null;
175	
176	  // Tell the visitor's widget this agent is composing, throttled to ~once/2.5s.
177	  function pingTyping() {
178	    if (!selectedId) return;
179	    const now = Date.now();
180	    if (now - lastTypingPingRef.current < 2500) return;
181	    lastTypingPingRef.current = now;
182	    void signalAgentTyping(selectedId);
183	  }
184	
185	  useEffect(() => {
186	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
187	  }, [selected?.messages.length, selectedId]);
188	
189	  function doReply() {
190	    if (!selected || pending) return;
191	    if (!draft.trim() && !pendingImage) return;
192	    const body = draft;
193	    setError("");
194	
195	    if (pendingImage) {
196	      const fd = new FormData();
197	      fd.append("conversationId", selected.id);
198	      fd.append("file", pendingImage.file);
199	      if (body.trim()) fd.append("body", body.trim());
200	      start(async () => {
201	        const res = await replyWithAttachment(fd);
202	        if (res.error) {
203	          setError(res.error);
204	          return;
205	        }
206	        setDraft("");
207	        clearImage();
208	        await refresh();
209	      });
210	      return;
211	    }
212	
213	    start(async () => {
214	      const res = await replyToConversation(selected.id, body);
215	      if (res.error) {
216	        setError(res.error);
217	        return;
218	      }
219	      setDraft("");
220	      await refresh();
221	    });
222	  }
223	
224	  function doClose() {
225	    if (!selected) return;
226	    start(async () => {
227	      await closeConversation(selected.id);
228	      await refresh();
229	    });
230	  }
231	
232	  function doCloseAll() {
233	    const openCount = convos.filter((c) => c.status !== "CLOSED").length;
234	    if (openCount === 0 || pending) return;
235	    if (
236	      typeof window !== "undefined" &&
237	      !window.confirm(`Close all ${openCount} open conversation${openCount === 1 ? "" : "s"}?`)
238	    ) {
239	      return;
240	    }
241	    start(async () => {
242	      await closeAllConversations();
243	      await refresh();
244	    });
245	  }
246	
247	  function doAssign() {
248	    if (!selected) return;
249	    start(async () => {
250	      await assignConversation(selected.id);
251	      await refresh();
252	    });
253	  }
254	
255	  function label(c: Convo): string {
256	    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
257	  }
258	
259	  // Who authored a given message, from the staff perspective. The bot ("bot") is
260	  // always the AI assistant; a human reply ("agent") is attributed to the agent
261	  // handling the thread (assignedToName), or a generic "Support agent" fallback.
262	  function messageAuthor(c: Convo, m: Msg): string {
263	    if (m.sender === "bot") return "Nxeon Assistant · AI";
264	    if (m.sender === "agent") return c.assignedToName || "Support agent";
265	    return label(c);
266	  }
267	
268	  // One-line preview of the last message for the list, prefixed by who sent it.
269	  function lastPreview(c: Convo): string {
270	    const last = c.messages[c.messages.length - 1];
271	    if (!last) return "…";
272	    const body = last.body || (last.attachment ? "📎 image" : "");
273	    if (last.sender === "agent") return `You: ${body}`;
274	    if (last.sender === "bot") return `AI: ${body}`;
275	    return body;
276	  }
277	
278	  const q = query.trim().toLowerCase();
279	  const filtered = q
280	    ? convos.filter((c) => {
281	        const haystack = [
282	          c.name,
283	          c.email,
284	          c.visitorId,
285	          c.assignedToName,
286	          ...c.messages.map((m) => m.body),
287	        ]
288	          .filter(Boolean)
289	          .join(" ")
290	          .toLowerCase();
291	        return haystack.includes(q);
292	      })
293	    : convos;
294	
295	  const openCount = convos.filter((c) => c.status !== "CLOSED").length;
296	
297	  return (
298	    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
299	      {/* Conversation list */}
300	      <div className="card flex max-h-[70vh] flex-col p-0">
301	        {/* Toolbar: search + bulk close */}
302	        <div className="space-y-2 border-b border-white/10 p-2.5">
303	          <div className="relative">
304	            <svg
305	              width="15"
306	              height="15"
307	              viewBox="0 0 24 24"
308	              fill="none"
309	              stroke="currentColor"
310	              strokeWidth="2"
311	              strokeLinecap="round"
312	              strokeLinejoin="round"
313	              className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500"
314	              aria-hidden
315	            >
316	              <circle cx="11" cy="11" r="7" />
317	              <path d="m21 21-4.3-4.3" />
318	            </svg>
319	            <input
320	              type="search"
321	              value={query}
322	              onChange={(e) => setQuery(e.target.value)}
323	              placeholder="Search name, email or message…"
324	              aria-label="Search conversations"
325	              className="input w-full py-1.5 pl-8 pr-2 text-xs"
326	            />
327	          </div>
328	          <div className="flex items-center justify-between gap-2 px-0.5">
329	            <span className="text-[11px] text-slate-500">
330	              {filtered.length === convos.length
331	                ? `${convos.length} conversation${convos.length === 1 ? "" : "s"}`
332	                : `${filtered.length} of ${convos.length}`}
333	            </span>
334	            <button
335	              type="button"
336	              onClick={doCloseAll}
337	              disabled={pending || openCount === 0}
338	              className="rounded-lg border border-white/10 px-2 py-0.5 text-[11px] text-slate-300 transition hover:bg-white/[0.06] disabled:opacity-40"
339	            >
340	              Close all{openCount > 0 ? ` (${openCount})` : ""}
341	            </button>
342	          </div>
343	        </div>
344	
345	        <div className="flex-1 space-y-1 overflow-y-auto p-2">
346	          {convos.length === 0 && (
347	            <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
348	          )}
349	          {convos.length > 0 && filtered.length === 0 && (
350	            <p className="p-4 text-center text-sm text-slate-500">No matches for “{query}”.</p>
351	          )}
352	          {filtered.map((c) => {
353	            const active = c.id === selectedId;
354	            const closed = c.status === "CLOSED";
355	            return (
356	              <button
357	                key={c.id}
358	                onClick={() => setSelectedId(c.id)}
359	                className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
360	                  active
361	                    ? "border-brand-500/50 bg-brand-500/10"
362	                    : "border-transparent hover:bg-white/[0.04]"
363	                }`}
364	              >
365	                <div className="flex items-center justify-between gap-2">
366	                  <span
367	                    className={`truncate text-sm font-medium ${
368	                      closed ? "text-slate-400" : "text-slate-100"
369	                    }`}
370	                  >
371	                    {label(c)}
372	                  </span>
373	                  <div className="flex shrink-0 items-center gap-1.5">
374	                    {c.unreadForAgent && !closed && (
375	                      <span
376	                        className="h-2 w-2 rounded-full bg-amber-400"
377	                        title="Needs a reply"
378	                      />
379	                    )}
380	                    {closed && (
381	                      <span className="rounded bg-white/[0.06] px-1.5 py-0.5 text-[9px] font-medium uppercase tracking-wide text-slate-500">
382	                        closed
383	                      </span>
384	                    )}
385	                  </div>
386	                </div>
387	                <div className="mt-0.5 flex items-center justify-between gap-2">
388	                  <span className="truncate text-xs text-slate-400">{lastPreview(c)}</span>
389	                  <span className="shrink-0 text-[10px] text-slate-500">
390	                    {timeAgo(c.lastMessageAt)}
391	                  </span>
392	                </div>
393	              </button>
394	            );
395	          })}
396	        </div>
397	      </div>
398	
399	      {/* Thread view */}
400	      <div className="card flex max-h-[70vh] flex-col p-0">
401	        {!selected ? (
402	          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
403	            Select a conversation to view it.
404	          </div>
405	        ) : (
406	          <>
407	            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
408	              <div>
409	                <p className="text-sm font-semibold text-slate-100">{label(selected)}</p>
410	                <p className="text-xs text-slate-400">
411	                  {selected.email || "no email"}
412	                  {selected.userId ? " · registered customer" : " · guest"} ·{" "}
413	                  {selected.status.toLowerCase()}
414	                  {selected.assignedToName ? ` · assigned to ${selected.assignedToName}` : ""}
415	                </p>
416	              </div>
417	              <div className="flex items-center gap-2">
418	                <button
419	                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
420	                  onClick={doAssign}
421	                  disabled={pending}
422	                >
423	                  Assign to me
424	                </button>
425	                {selected.status !== "CLOSED" && (
426	                  <button
427	                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
428	                    onClick={doClose}
429	                    disabled={pending}
430	                  >
431	                    Close
432	                  </button>
433	                )}
434	              </div>
435	            </div>
436	
437	            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
438	              {selected.messages.map((m) => {
439	                const isCustomer = m.sender === "visitor";
440	                const isBot = m.sender === "bot";
441	                // Staff (human agent + AI bot) sit on the right, opposite the
442	                // customer, each with a distinct bubble and an author label.
443	                return (
444	                  <div
445	                    key={m.id}
446	                    className={`flex flex-col ${isCustomer ? "items-start" : "items-end"}`}
447	                  >
448	                    <span
449	                      className={`mb-0.5 flex items-center gap-1 px-1 text-[11px] font-medium ${
450	                        isBot ? "text-brand-300" : isCustomer ? "text-slate-400" : "text-brand-200"
451	                      }`}
452	                    >
453	                      {isBot && <BotIcon />}
454	                      {messageAuthor(selected, m)}
455	                    </span>
456	                    <div
457	                      className={`max-w-[75%] space-y-1.5 whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
458	                        isCustomer
459	                          ? "border border-white/10 bg-white/[0.06] text-slate-200"
460	                          : isBot
461	                            ? "border border-brand-400/30 bg-brand-500/10 text-slate-100"
462	                            : "bg-brand-500 text-white"
463	                      }`}
464	                    >
465	                      {m.attachment && (
466	                        <a
467	                          href={`/api/chat/attachment/${m.attachment.id}`}
468	                          target="_blank"
469	                          rel="noopener noreferrer"
470	                          className="block"
471	                        >
472	                          {/* eslint-disable-next-line @next/next/no-img-element */}
473	                          <img
474	                            src={`/api/chat/attachment/${m.attachment.id}`}
475	                            alt="attachment"
476	                            className="max-h-48 max-w-full rounded-lg border border-white/10 object-contain"
477	                          />
478	                        </a>
479	                      )}
480	                      {m.body && <div>{m.body}</div>}
481	                      <div
482	                        className={`mt-1 text-[10px] ${
483	                          isCustomer || isBot ? "text-slate-500" : "text-white/60"
484	                        }`}
485	                      >
486	                        {timeAgo(m.createdAt)}
487	                      </div>
488	                    </div>
489	                  </div>
490	                );
491	              })}
492	              {selected.visitorTyping && (
493	                <div className="flex justify-start" aria-live="polite">
494	                  <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-3.5 py-2.5">
495	                    <TypingDots />
496	                    <span className="text-[11px] text-slate-400">{label(selected)} is typing…</span>
497	                  </div>
498	                </div>
499	              )}
500	            </div>
501	
502	            <div className="border-t border-white/10 px-4 py-3">
503	              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
504	              {pendingImage && (
505	                <div className="mb-2 flex items-center gap-2">
506	                  <div className="relative">
507	                    {/* eslint-disable-next-line @next/next/no-img-element */}
508	                    <img
509	                      src={pendingImage.url}
510	                      alt="preview"
511	                      className="h-14 w-14 rounded-lg border border-white/10 object-cover"
512	                    />
513	                    <button
514	                      type="button"
515	                      aria-label="Remove image"
516	                      onClick={clearImage}
517	                      className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-slate-800 text-slate-200 ring-1 ring-white/20 hover:bg-slate-700"
518	                    >
519	                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
520	                        <path d="M18 6 6 18M6 6l12 12" />
521	                      </svg>
522	                    </button>
523	                  </div>
524	                  <span className="truncate text-xs text-slate-400">{pendingImage.file.name}</span>
525	                </div>
526	              )}
527	              <input
528	                ref={fileInputRef}
529	                type="file"
530	                accept={ACCEPT_IMAGES}
531	                className="hidden"
532	                onChange={(e) => pickImage(e.target.files?.[0])}
533	              />
534	              <div className="flex items-end gap-2">
535	                <button
536	                  type="button"
537	                  aria-label="Attach image"
538	                  onClick={() => fileInputRef.current?.click()}
539	                  disabled={pending}
540	                  className="shrink-0 rounded-lg p-2 text-slate-400 hover:bg-white/10 hover:text-slate-200 disabled:opacity-50"
541	                >
542	                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
543	                    <path d="M21.44 11.05 12.25 20.24a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
544	                  </svg>
545	                </button>
546	                <textarea
547	                  className="input min-h-[2.5rem] flex-1 resize-none py-2 text-sm"
548	                  placeholder="Type your reply…"
549	                  value={draft}
550	                  maxLength={5000}
551	                  rows={1}
552	                  onChange={(e) => {
553	                    setDraft(e.target.value);
554	                    if (e.target.value.trim()) pingTyping();
555	                  }}
556	                  onPaste={onPaste}
557	                  onKeyDown={(e) => {
558	                    if (e.key === "Enter" && !e.shiftKey) {
559	                      e.preventDefault();
560	                      doReply();
561	                    }
562	                  }}
563	                  disabled={pending}
564	                />
565	                <button
566	                  className="btn-primary shrink-0 px-4 py-2 text-sm"
567	                  onClick={doReply}
568	                  disabled={pending || (!draft.trim() && !pendingImage)}
569	                >
570	                  {pending ? "…" : "Reply"}
571	                </button>
572	              </div>
573	            </div>
574	          </>
575	        )}
576	      </div>
577	    </div>
578	  );
579	}
