1	import { NextResponse } from "next/server";
2	import { db } from "@/lib/db";
3	import { currentUser } from "@/lib/auth";
4	import { checkRateLimit } from "@/lib/rate-limit";
5	import { trustedClientIp } from "@/app/api/_lib/client-ip";
6	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
7	import { readTyping } from "@/lib/chat-typing";
8	import { readBotStep } from "@/lib/chat-bot-step";
9	import { mirrorChatMessageToDiscord } from "@/lib/discord-bridge";
10	
11	export const runtime = "nodejs";
12	
13	/**
14	 * Public live-chat endpoint used by <ChatWidget/>.
15	 *
16	 * POST /api/chat  — start or continue a conversation for a visitorId.
17	 * GET  /api/chat?visitorId=…  — poll the visitor's open conversation.
18	 *
19	 * Everything is scoped strictly by the client-supplied `visitorId`; we never
20	 * return another visitor's data. Signed-in customers additionally get their
21	 * `userId` stamped on the conversation. Unauthenticated + write-heavy, so the
22	 * POST path is rate-limited per IP.
23	 */
24	
25	function clip(v: unknown, max: number): string | null {
