75	export async function POST(req: Request) {
76	  const rl = checkRateLimit(`chat:${trustedClientIp(req)}`, { max: 30, windowMs: 60_000 });
77	  if (!rl.ok) {
78	    return NextResponse.json(
79	      { error: "Too many messages. Please slow down." },
80	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
81	    );
82	  }
83	
84	  const raw = (await req.json().catch(() => ({}))) as Record<string, unknown>;
85	  const visitorId = clip(raw.visitorId, 100);
86	  const conversationId = clip(raw.conversationId, 40);
87	  const body = clip(raw.body, 5000);
88	  const name = clip(raw.name, 120);
89	  const email = clip(raw.email, 200);
90	
91	  if (!visitorId) return NextResponse.json({ error: "Missing visitorId." }, { status: 400 });
92	  if (!body) return NextResponse.json({ error: "Message cannot be empty." }, { status: 400 });
93	
94	  const user = await currentUser();
95	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
96	    user?.id ? [{ userId: user.id }] : [],
97	  );
98	
99	  // If the client names a conversation it owns, continue it (resuming past
100	  // history, reopening if it was closed). Otherwise start a brand-new one — we
101	  // no longer auto-resume the latest, so returning gives a fresh chat while old
102	  // threads stay available in the history list.
103	  let convo = conversationId
104	    ? await db.chatConversation.findFirst({
105	        where: { id: conversationId, OR: ownedBy },
106	        select: { id: true, name: true, email: true },
107	      })
108	    : null;
109	
110	  if (!convo) {
111	    // Anonymous (not signed in) visitors must give a name + valid email before
112	    // starting. Signed-in customers already have both, so they're never asked.
113	    if (!user) {
114	      const nm = name ?? null;
115	      const em = email ?? null;
116	      if (!nm || !em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em)) {
117	        return NextResponse.json(
118	          { error: "Please add your name and a valid email to start the chat.", needIdentity: true },
119	          { status: 400 },
120	        );
121	      }
122	    }
123	    convo = await db.chatConversation.create({
124	      data: {
125	        visitorId,
126	        userId: user?.id ?? null,
127	        name: name ?? user?.name ?? null,
128	        email: email ?? user?.email ?? null,
129	      },
130	      select: { id: true, name: true, email: true },
131	    });
132	  }
133	
134	  await db.$transaction([
135	    db.chatMessage.create({
136	      data: { conversationId: convo.id, sender: "visitor", body },
137	    }),
138	    db.chatConversation.update({
139	      where: { id: convo.id },
140	      data: {
141	        status: "OPEN", // reopen if the visitor is resuming a closed thread
142	        unreadForAgent: true,
143	        lastMessageAt: new Date(),
144	        // Backfill identity / link account if it arrives after creation.
145	        ...(user?.id ? { userId: user.id } : {}),
146	        ...(name && !convo.name ? { name } : {}),
147	        ...(email && !convo.email ? { email } : {}),
148	      },
149	    }),
150	  ]);
151	
152	  // Discord bridge (Phase 1 mirror): best-effort, never blocks the visitor's
153	  // message — creates the guild channel on the visitor's FIRST message, posts
154	  // into the existing channel on every message after — see
155	  // lib/discord-bridge.ts's mirrorChatMessageToDiscord.
156	  await mirrorChatMessageToDiscord(convo.id, body, "visitor");
157	
158	  // AI assistant + human-handoff orchestration (see lib/kb-run.ts). Best-effort
159	  // and fully wrapped: it must NEVER break live chat, and it stays silent once a
160	  // human has engaged.
161	  try {
162	    const { runAssistant } = await import("@/lib/kb-run");
163	    await runAssistant({ conversationId: convo.id, visitorId, currentBody: body });
164	  } catch {
165	    /* assistant is non-essential — never fail the visitor's message on it */
166	  }
167	
168	  const full = await db.chatConversation.findUnique({
169	    where: { id: convo.id },
170	    include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
171	  });
172	  return NextResponse.json(serialize(full!), { headers: NO_STORE_HEADERS });
173	}
