175	export async function GET(req: Request) {
176	  const url = new URL(req.url);
177	  const visitorId = clip(url.searchParams.get("visitorId"), 100);
178	  const conversationId = clip(url.searchParams.get("conversationId"), 40);
179	  if (!visitorId) {
180	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
181	  }
182	
183	  const user = await currentUser();
184	  const ownedBy = [{ visitorId } as Record<string, unknown>].concat(
185	    user?.id ? [{ userId: user.id }] : [],
186	  );
187	
188	  // Poll a specific conversation when named (scoped to the visitor/user), else
189	  // the most recent open thread for back-compat.
190	  let convo = conversationId
191	    ? await db.chatConversation.findFirst({
192	        where: { id: conversationId, OR: ownedBy },
193	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
194	      })
195	    : await db.chatConversation.findFirst({
196	        where: { visitorId, status: "OPEN" },
197	        orderBy: { lastMessageAt: "desc" },
198	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
199	      });
200	
201	  if (!convo) {
202	    return NextResponse.json({ conversation: null, messages: [] }, { headers: NO_STORE_HEADERS });
203	  }
204	
205	  // If the bot is waiting on a live agent, let the poll drive the handoff window:
206	  // post the "no agents available" fallback once it elapses, then refresh so the
207	  // visitor sees it on this same poll rather than the next one.
208	  if (convo.botEscalatedAt) {
209	    try {
210	      const { checkEscalationTimeout } = await import("@/lib/kb-run");
211	      await checkEscalationTimeout(convo.id);
212	      const refreshed = await db.chatConversation.findFirst({
213	        where: { id: convo.id },
214	        include: { messages: { orderBy: { createdAt: "asc" }, include: { attachment: true } } },
215	      });
216	      if (refreshed) convo = refreshed;
217	    } catch {
218	      /* non-essential */
219	    }
220	  }
221	
222	  // Reading the thread clears the visitor-facing unread flag.
223	  if (convo.unreadForUser) {
224	    await db.chatConversation
225	      .update({ where: { id: convo.id }, data: { unreadForUser: false } })
226	      .catch(() => {});
227	  }
228	
229	  // The whole support transcript, plus the name/email the visitor gave. The
230	  // `?visitorId=` in the URL is the ONLY thing scoping it, which makes the URL
231	  // itself the secret — precisely the shape a shared cache must never store.
232	  //
233	  // `typing.agent` tells the widget whether a support agent is composing a reply
234	  // right now; it self-expires, so a stale poll can only ever under-report.
235	  // `botStep` is the AI agent's current live "thinking" step (e.g. "Checking
236	  // your billing…"), sourced from lib/chat-bot-step.ts; it self-expires too, so
237	  // a stalled/crashed model call can never leave a stuck label on screen.
238	  return NextResponse.json(
239	    { ...serialize(convo), typing: { agent: readTyping(convo.id).agent }, botStep: readBotStep(convo.id) },
240	    { headers: NO_STORE_HEADERS },
241	  );
242	}
