43	/** Extract a hidden `[[cards: key1, key2]]` directive from a bot reply, returning
44	 *  the visible body (directive stripped) and the card keys. */
45	function parseCardDirective(reply: string): { body: string; keys: string[] } {
46	  const m = reply.match(/\[\[\s*cards?\s*:\s*([^\]]+)\]\]/i);
47	  if (!m) return { body: reply, keys: [] };
48	  const keys = m[1]
49	    .split(",")
50	    .map((s) => s.trim())
51	    .filter(Boolean);
52	  const body = reply.replace(m[0], "").replace(/\n{3,}/g, "\n\n").trim();
53	  return { body, keys };
54	}
