56	/** One parsed (not-yet-resolved) `[[action: type=…, id=…, label="…"]]` spec. */
57	type ActionSpec = { kind: string; id: string; label?: string };
58	
59	/** Extract every hidden `[[action: ...]]` directive from a bot reply — the
60	 *  account-action-card sibling of `[[cards: ...]]` (see lib/kb-tools.ts's
61	 *  resolveActionCard for what these become). Attribute order doesn't matter;
62	 *  unrecognized attributes are ignored. Directives are stripped from the
63	 *  visible body regardless of whether they end up resolving to a real card. */
64	function parseActionDirectives(reply: string): { body: string; specs: ActionSpec[] } {
65	  const specs: ActionSpec[] = [];
66	  const re = /\[\[\s*action\s*:\s*([^\]]+)\]\]/gi;
67	  const body = reply
68	    .replace(re, (_full, attrsRaw: string) => {
69	      const attrs: Record<string, string> = {};
70	      // key=value pairs, comma-separated; value optionally double-quoted.
71	      const attrRe = /(\w+)\s*=\s*(?:"([^"]*)"|([^,]+))/g;
72	      let am: RegExpExecArray | null;
73	      while ((am = attrRe.exec(attrsRaw)) !== null) {
74	        attrs[am[1].toLowerCase()] = (am[2] ?? am[3] ?? "").trim();
75	      }
76	      if (attrs.type && attrs.id) {
77	        specs.push({ kind: attrs.type.toLowerCase(), id: attrs.id, label: attrs.label });
78	      }
79	      return "";
80	    })
81	    .replace(/\n{3,}/g, "\n\n")
82	    .trim();
83	  return { body, specs };
84	}
