104	/** Atomically move the conversation into the "waiting for a live agent" state,
105	 *  post the holding message, and email an agent. No-op if already escalated. */
106	async function escalate(convo: ConvoLite, lastBody: string): Promise<void> {
107	  const claim = await db.chatConversation.updateMany({
108	    where: { id: convo.id, botEscalatedAt: null },
109	    data: { botEscalatedAt: new Date(), unreadForAgent: true },
110	  });
111	  if (claim.count !== 1) return; // someone/something already escalated
112	
113	  await db.chatMessage.create({
114	    data: { conversationId: convo.id, sender: "bot", body: WAIT_MSG },
115	  });
116	  await mirrorChatMessageToDiscord(convo.id, WAIT_MSG, "bot");
117	
118	  // Email an available agent (best-effort). They have the window to jump in.
119	  try {
120	    if (await mailConfigured()) {
121	      const to = (await getSetting("kb_bot_agent_email", "")) || (await getSetting("support_email", ""));
122	      if (to) {
123	        const who = convo.name
124	          ? `${convo.name}${convo.email ? ` (${convo.email})` : ""}`
125	          : convo.email || "A website visitor";
126	        const html = layout(
127	          "A visitor wants to talk to a human",
128	          `<p><strong>${esc(who)}</strong> is asking for a live agent in the website chat.</p>
129	           <p style="color:#64748b">Latest message: “${esc(lastBody.slice(0, 300))}”</p>
130	           <p>Hop in within the next few minutes to take over — after that they'll be offered a callback instead.</p>
131	           ${button(ADMIN_CHAT_URL, "Open the live chat inbox")}`,
132	        );
133	        await sendMail({
134	          to,
135	          subject: "🔔 Live chat — a visitor wants a human",
136	          html,
137	          replyTo: convo.email || undefined,
138	        });
139	      }
140	    }
141	  } catch {
142	    /* email is best-effort; the conversation is already flagged in the inbox */
143	  }
