190	/**
191	 * Evaluate the assistant for a just-received visitor message. Creates a bot
192	 * reply (or runs the handoff flow) when appropriate. `images` are the base64
193	 * blocks for an image the visitor just sent (upload path), if any.
194	 */
195	export async function runAssistant(args: {
196	  conversationId: string;
197	  visitorId: string;
198	  currentBody: string;
199	  images?: LlmImage[];
200	}): Promise<void> {
201	  try {
202	    if ((await getSetting("kb_bot_enabled", "false")) !== "true") return;
203	
204	    const convo = await db.chatConversation.findUnique({
205	      where: { id: args.conversationId },
206	      select: {
207	        id: true,
208	        visitorId: true,
209	        userId: true,
210	        name: true,
211	        email: true,
212	        assignedToId: true,
213	        botEscalatedAt: true,
214	        messages: { orderBy: { createdAt: "asc" }, select: { sender: true, body: true } },
215	      },
216	    });
217	    if (!convo) return;
218	
219	    // Never talk over a human: silent once an agent replied or was assigned.
220	    const agentReplied = convo.messages.some((m) => m.sender === "agent");
221	    if (agentReplied || convo.assignedToId) return;
222	
223	    // Already waiting on a live agent — stay quiet; just check the timeout.
224	    if (convo.botEscalatedAt) {
225	      await checkEscalationTimeout(convo.id);
226	      return;
227	    }
228	
229	    // Guardrail: per-conversation reply cap → escalate instead of looping.
230	    const botCount = convo.messages.filter((m) => m.sender === "bot").length;
231	    const maxReplies = await getSettingInt("kb_bot_max_replies", 16);
232	    if (maxReplies > 0 && botCount >= maxReplies) {
233	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
234	      return;
235	    }
236	
237	    // Guardrail: platform-wide daily reply cap (soft cost ceiling). Over it, we
238	    // still answer — just from the token-free retrieval path (no paid call).
239	    let overDaily = false;
240	    const dailyCap = await getSettingInt("kb_bot_daily_cap", 1000);
241	    if (dailyCap > 0) {
242	      const since = new Date();
243	      since.setHours(0, 0, 0, 0);
244	      const used = await db.kbBotLog.count({
245	        where: { createdAt: { gte: since }, kind: { in: ["answer", "offer"] } },
246	      });
247	      overDaily = used >= dailyCap;
248	    }
249	
250	    const history = toHistory(convo.messages.slice(0, -1));
251	    const result = await kbAnswer(args.currentBody, {
252	      history,
253	      images: args.images,
254	      visitorName: firstName(convo.name),
255	      userId: convo.userId,
256	      noLlm: overDaily,
257	      conversationId: convo.id,
258	    });
259	
260	    // A live agent is ONLY brought in when the visitor explicitly asks for one
261	    // (humanIntent → kind "handoff"). The bot never offers or escalates on its own.
262	    if (result.kind === "handoff") {
263	      await escalate({ id: convo.id, visitorId: convo.visitorId, name: convo.name, email: convo.email }, args.currentBody);
264	      return;
265	    }
266	
267	    if (result.reply) {
268	      // Resolve any plan cards to render with this reply: the LLM signals them
269	      // with a hidden [[cards: key1, key2]] directive; the retrieval fallback
270	      // supplies result.cardKeys. Cards are looked up from the real catalog, so
271	      // the model can only ever pick keys — prices/features are never invented.
272	      const parsedCards = parseCardDirective(result.reply);
273	      // Account-action cards are the same mechanism's sibling: [[action: ...]]
274	      // directives, resolved against THIS customer's own data (never invented —
275	      // see resolveActionCard's ownership checks). Parsed from whatever text
276	      // parseCardDirective left behind, so both directives can coexist.
277	      const parsedActions = parseActionDirectives(parsedCards.body);
278	      const keys = [...(result.cardKeys ?? []), ...parsedCards.keys];
279	      const planCards: ChatCard[] = keys.length
280	        ? getPlanCards(keys).map((c) => ({ ...c, type: "plan" as const }))
281	        : [];
282	      const actionCards = (
283	        await Promise.all(
284	          parsedActions.specs
285	            .slice(0, 3) // never render a wall of cards
286	            .map((spec) => resolveActionCard(convo.userId, spec.kind, spec.id, spec.label)),
287	        )
288	      ).filter((c): c is AccountActionCard => c !== null);
289	      const cards: ChatCard[] = [...planCards, ...actionCards];
290	      await db.chatMessage.create({
291	        data: {
292	          conversationId: convo.id,
293	          sender: "bot",
294	          body: parsedActions.body,
295	          cardsJson: cards.length ? JSON.stringify(cards) : null,
296	        },
297	      });
298	      await mirrorChatMessageToDiscord(convo.id, parsedActions.body, "bot");
299	    }
300	    // Log coverage. A HARD model failure (bad/unfunded key, API outage) is logged
301	    // as "llm_error" — distinct from an expected "degraded"/over-cap — so the
302	    // admin KB dashboard shows the bot is broken instead of it failing silently.
303	    await db.kbBotLog
304	      .create({
305	        data: {
306	          visitorId: args.visitorId,
307	          conversationId: convo.id,
308	          question: args.currentBody.slice(0, 500),
309	          kind: result.llmFailure === "error" ? "llm_error" : result.kind,
310	          matchedTitle: result.matchedTitle ?? null,
311	        },
312	      })
313	      .catch(() => {});
314	  } catch {
315	    /* assistant is non-essential — never fail the visitor's message on it */
316	  }
317	}
