46	/**
47	 * Resolve staff user ids to display names in one query. Not a "use server"
48	 * export (it takes non-serializable args and isn't called from the client);
49	 * used internally to attach `assignedToName` to inbox payloads so the admin
50	 * thread view can label each human reply with the agent handling it.
51	 */
52	async function resolveStaffNames(
53	  ids: (string | null)[]
54	): Promise<Map<string, string>> {
55	  const unique = Array.from(new Set(ids.filter((v): v is string => !!v)));
56	  if (unique.length === 0) return new Map();
57	  const users = await db.user.findMany({
58	    where: { id: { in: unique } },
59	    select: { id: true, name: true },
60	  });
61	  return new Map(users.map((u) => [u.id, u.name]));
62	}
