164	export async function replyWithAttachment(
165	  formData: FormData
166	): Promise<{ error?: string; ok?: boolean }> {
167	  const staff = await requireArea("support");
168	
169	  // Throttle staff uploads defensively (shared limiter, keyed by staff id).
170	  const rl = checkRateLimit(`chat-upload:${staff.id}`, { max: 30, windowMs: 60_000 });
171	  if (!rl.ok) return { error: "Too many uploads. Please slow down." };
