177	  if (typeof id !== "string" || !id) return { error: "Invalid conversation." };
178	  const body = typeof rawBody === "string" ? rawBody.trim().slice(0, 5000) : "";
179	  if (!(file instanceof File)) return { error: "No image provided." };
180	  if (file.size > 5 * 1024 * 1024) return { error: "Image is larger than 5 MB." };
181	
182	  const convo = await db.chatConversation.findUnique({ where: { id } });
183	  if (!convo) return { error: "Conversation not found." };
184	
185	  const bytes = Buffer.from(await file.arrayBuffer());
186	  const check = validateImageBytes(bytes, file.type);
187	  if (!check.ok) return { error: check.error };
188	
189	  await db.$transaction(async (tx) => {
190	    const msg = await tx.chatMessage.create({
191	      data: { conversationId: id, sender: "agent", body },
192	    });
193	    await tx.chatAttachment.create({
194	      data: {
195	        messageId: msg.id,
