216	        data: {
217	          userId: convo.userId,
218	          title: "New reply in your live chat",
219	          href: "/dashboard",
220	        },
221	      })
222	      .catch(() => {});
223	  }
224	
225	  // Discord bridge (Phase 1 mirror): the bridge doesn't forward image bytes
226	  // (see lib/discord-bridge.ts), so mirror a short placeholder plus any caption.
227	  await mirrorChatMessageToDiscord(id, body ? `📎 ${body}` : "📎 (image attachment — view in /admin/chat)", "agent");
228	
229	  revalidatePath("/admin/chat");
230	  return { ok: true };
231	}
