37	export function VoiceMeter({ stream }: { stream: MediaStream | null }) {
38	  const canvasRef = useRef<HTMLCanvasElement>(null);
39	  useEffect(() => {
40	    if (!stream) return;
41	    const canvas = canvasRef.current;
42	    if (!canvas) return;
43	    const ctx2d = canvas.getContext("2d");
44	    if (!ctx2d) return;
45	    let raf = 0;
46	    let audioCtx: AudioContext | null = null;
47	    try {
48	      const AC =
49	        window.AudioContext ||
50	        (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
51	      if (!AC) return;
52	      audioCtx = new AC();
53	      const src = audioCtx.createMediaStreamSource(stream);
54	      const analyser = audioCtx.createAnalyser();
55	      analyser.fftSize = 128;
56	      analyser.smoothingTimeConstant = 0.75;
57	      src.connect(analyser);
58	      const bins = new Uint8Array(analyser.frequencyBinCount);
59	      const BARS = 5;
60	      const step = Math.max(1, Math.floor(bins.length / BARS));
61	      const draw = () => {
62	        analyser.getByteFrequencyData(bins);
63	        const w = canvas.width;
64	        const h = canvas.height;
65	        ctx2d.clearRect(0, 0, w, h);
66	        const bw = w / BARS;
67	        for (let i = 0; i < BARS; i++) {
68	          let sum = 0;
69	          for (let j = 0; j < step; j++) sum += bins[i * step + j] ?? 0;
70	          const v = sum / step / 255;
71	          const bh = Math.max(2, v * h);
72	          ctx2d.fillStyle = "#8a70fb";
73	          ctx2d.fillRect(i * bw + bw * 0.25, (h - bh) / 2, bw * 0.5, bh);
74	        }
75	        raf = requestAnimationFrame(draw);
76	      };
77	      draw();
78	    } catch {
79	      /* no meter */
80	    }
81	    return () => {
82	      if (raf) cancelAnimationFrame(raf);
83	      try {
84	        void audioCtx?.close();
85	      } catch {
86	        /* ignore */
87	      }
88	    };
89	  }, [stream]);
90	  return <canvas ref={canvasRef} width={46} height={16} className="h-4 w-[46px]" aria-hidden />;
